const item = $input.first()?.json || {};
const data = item.body || item;

const ticketId = Number(data.ticket_id || data.id || 1);
const staffId = Number(data.staff_id || 4);
const caseType = (data.case_type || data.category || 'GENERAL').toUpperCase();
const status = (data.status || data.action || 'RESOLVED').toUpperCase();
const responseNote = data.response_note || data.resolution || data.resolution_note || data.message || 'Đã kiểm tra và xử lý hoàn tất sự cố cho khách hàng.';
const compensation = data.compensation || data.voucher || '';

return [{
  json: {
    ticket_id: ticketId,
    staff_id: staffId,
    case_type: caseType,
    status: status,
    response_note: responseNote,
    compensation: compensation
  }
}];

